<?php declare(strict_types=1);$data=is_array($data??null)?$data:[];$base=appBasePath();$canRetry=in_array('administration.integration_events.retry',$_SESSION['auth']['permissions']??[],true);?>
<?php if(!empty($data['notice'])):?><div class="alert alert-success"><?=e($data['notice'])?></div><?php endif;?><?php if(!empty($data['error'])):?><div class="alert alert-danger"><?=e($data['error'])?></div><?php endif;?>
<section class="card"><h2>Worker health</h2><div class="table-responsive"><table class="data-table"><thead><tr><th>Task</th><th>Last run</th><th>Last success</th><th>Last failure</th></tr></thead><tbody><?php foreach($data['health']??[] as $row):?><tr><td><?=e($row['task_name'])?></td><td><?=e($row['last_run']??'Never')?></td><td><?=e($row['last_success']??'Never')?></td><td><?=e($row['last_failure']??'Never')?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Filters</h2><form method="get" action="<?=e($base)?>/administration/integration-events"><label>Status<select name="status"><option value="">All</option><?php foreach(['pending','processing','processed','failed'] as $s):?><option <?=($data['filters']['status']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><label>Event type<input name="event_type" value="<?=e($data['filters']['event_type']??'')?>"></label><label>From<input type="date" name="date_from" value="<?=e($data['filters']['date_from']??'')?>"></label><label>To<input type="date" name="date_to" value="<?=e($data['filters']['date_to']??'')?>"></label><button class="btn btn-primary">Filter</button></form></section>
<section class="card table-card"><h2>Integration events</h2><div class="table-responsive"><table class="data-table"><thead><tr><th>ID</th><th>Event</th><th>Aggregate</th><th>Status</th><th>Attempts</th><th>Created / retry</th><th>Failure</th><th>Action</th></tr></thead><tbody><?php foreach($data['events']??[] as $row):?><tr><td><?=e($row['event_id'])?></td><td><?=e($row['event_type'])?></td><td><?=e($row['aggregate_type'].' / '.$row['aggregate_id'])?></td><td><?=e($row['status'])?></td><td><?=e($row['attempts'])?></td><td><?=e($row['created_at'])?><br><?=e($row['available_at']??'—')?></td><td><?=e($row['last_error']??'—')?></td><td><?php if($canRetry&&$row['status']==='failed'):?><form method="post" action="<?=e($base)?>/administration/integration-events/<?=e($row['event_id'])?>/retry"><?=csrfField()?><button class="btn btn-secondary">Requeue</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
